CREATE TABLE IF NOT EXISTS public.bi_filtro_config (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, nome text NOT NULL, filtros jsonb NOT NULL DEFAULT '{}'::jsonb, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.bi_filtro_config ENABLE ROW LEVEL SECURITY; GRANT SELECT, INSERT, UPDATE, DELETE ON public.bi_filtro_config TO authenticated; GRANT ALL ON public.bi_filtro_config TO service_role; CREATE POLICY "bi_filtro_config: user sees own" ON public.bi_filtro_config FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "bi_filtro_config: user inserts own" ON public.bi_filtro_config FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "bi_filtro_config: user updates own" ON public.bi_filtro_config FOR UPDATE TO authenticated USING (user_id = auth.uid()); CREATE POLICY "bi_filtro_config: user deletes own" ON public.bi_filtro_config FOR DELETE TO authenticated USING (user_id = auth.uid());